use std::{path::{Path,PathBuf},sync::{Arc,Barrier,atomic::{AtomicBool,Ordering}},thread,time::{Duration,Instant}};
use runtime::ownership::{Registry,RegistryError,ThreadOwner,OwnerPermit,Lease};
use providers::{Message,Role,ContentBlock};
use rusqlite::{Connection,TransactionBehavior,params};
use serde_json::json;
const ROOT:&str="/home/turtton/.ghr/github.com/turtton/evorch/.worktrees/owner-checkpoint-metadata/target/owner-checkpoint-bench";
fn busy(e:&RegistryError)->bool { e.is_contention() }
fn make_messages(size:usize)->Vec<Message>{let mut v=Vec::new();let mut remaining=size.saturating_sub(128);while remaining>0{let len=remaining.min(2048);v.push(Message{role:Role::Assistant,content:vec![ContentBlock::Text{text:"x".repeat(len.max(24))}]});remaining=remaining.saturating_sub(len);}let extra=serde_json::to_vec(&v).unwrap().len().saturating_sub(size);let mut remove=extra;for msg in v.iter_mut().rev(){if let ContentBlock::Text{text}=&mut msg.content[0]{let n=remove.min(text.len().saturating_sub(24));text.truncate(text.len()-n);remove-=n;}}let actual=serde_json::to_vec(&v).unwrap().len();if actual<size{if let ContentBlock::Text{text}=&mut v[0].content[0]{text.push_str(&"x".repeat(size-actual));}}assert_eq!(serde_json::to_vec(&v).unwrap().len(),size);v}
fn outside(p:&OwnerPermit,msg:&[Message])->Result<(),RegistryError>{
 let serialized=serde_json::to_string(msg)?;
 let mut c=Connection::open_with_flags(&p.registry_path,rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE|rusqlite::OpenFlags::SQLITE_OPEN_NO_MUTEX)?;
 c.busy_timeout(Duration::from_secs(2))?;
 let tx=c.transaction_with_behavior(TransactionBehavior::Immediate)?;
 let state:String=tx.query_row("SELECT state FROM thread_owners WHERE thread_id=?1",[&p.thread_id],|r|r.get(0))?;
 let mut owner:ThreadOwner=serde_json::from_str(&state)?;owner.checkpoint(&p.lease)?;
 tx.execute("INSERT INTO owner_checkpoints VALUES (?1,?2,?3) ON CONFLICT(thread_id) DO UPDATE SET generation=excluded.generation,payload=excluded.payload",params![p.thread_id,p.lease.generation.to_string(),serialized])?;
 tx.execute("UPDATE thread_owners SET state=?2 WHERE thread_id=?1",params![p.thread_id,serde_json::to_string(&owner)?])?;tx.commit()?;Ok(())
}
fn checkpoint(p:&OwnerPermit,msg:&[Message],mode:&str)->Result<(),RegistryError>{if mode=="permit" {p.checkpoint(msg)} else if mode=="outside" {outside(p,msg)}else{Registry::open_existing(&p.registry_path)?.checkpoint_permit(p,msg).map(|_|())}}
#[derive(Default)]struct Stats{lat:Vec<f64>,oklat:Vec<f64>,attempt_busy:usize,failed:usize,other:Vec<String>,guard_calls:usize,ops:usize}
fn quant(x:&[f64],q:f64)->f64 {if x.is_empty(){return 0.;}x[((x.len()-1)as f64*q).ceil()as usize]}
fn stats(mut s:Stats)->serde_json::Value{s.lat.sort_by(f64::total_cmp);s.oklat.sort_by(f64::total_cmp);json!({"ops":s.ops,"ok":s.oklat.len(),"busy_attempts":s.attempt_busy,"failed":s.failed,"other_errors":s.other,"guard_calls":s.guard_calls,"p50_ms":quant(&s.lat,0.5),"p99_ms":quant(&s.lat,0.99),"max_ms":quant(&s.lat,1.),"success_p50_ms":quant(&s.oklat,0.5),"success_p99_ms":quant(&s.oklat,0.99)})}
fn merge(a:&mut Stats,mut b:Stats){a.lat.append(&mut b.lat);a.oklat.append(&mut b.oklat);a.attempt_busy+=b.attempt_busy;a.failed+=b.failed;a.other.append(&mut b.other);a.guard_calls+=b.guard_calls;a.ops+=b.ops;}
fn run(mode:String,size:usize,n:usize,m:usize,seconds:f64,hold_us:u64,rep:u64){
 assert!(["base","outside","small","retry","cache10","combo","permit"].contains(&mode.as_str()));
 let path=PathBuf::from(ROOT).join(format!("bench-worker152-{}-{}-{}-{}-{}.db",mode,size,n,rep,std::process::id()));
 let mut reg=Registry::open(&path).unwrap();let mut permits=Vec::new();
 for i in 0..n.max(m){let owner=ThreadOwner::new(format!("t{i}"),Lease{owner_id:"bench".into(),generation:1,expires_at:u64::MAX/2});reg.start(&owner).unwrap();permits.push(OwnerPermit{registry_path:path.clone(),thread_id:owner.thread_id,lease:owner.lease,run_id:None});}
 let messages=make_messages(if mode=="small"||mode=="combo"{1024}else{size});let payload_len=serde_json::to_vec(&messages).unwrap().len();
 // Warm every row: timed writes all change a 24-digit marker, so SQLite cannot optimize identical updates away.
 for p in permits.iter().take(n){reg.checkpoint_permit(p,&messages).unwrap();}drop(reg);
 let c=Connection::open(&path).unwrap();let journal:String=c.query_row("PRAGMA journal_mode",[],|r|r.get(0)).unwrap();let sync:i64=c.query_row("PRAGMA synchronous",[],|r|r.get(0)).unwrap();assert_eq!(journal,"delete");assert_eq!(sync,2);drop(c);
 let barrier=Arc::new(Barrier::new(n+m+1));let stop=Arc::new(AtomicBool::new(false));let mut writers=Vec::new();let mut readers=Vec::new();let started=Instant::now();
 for (id,p) in permits.iter().take(n).cloned().enumerate(){let b=barrier.clone();let stop=stop.clone();let mode=mode.clone();let mut msg=messages.clone();writers.push(thread::spawn(move||{let mut s=Stats::default();let mut seq=0usize;b.wait();while !stop.load(Ordering::Relaxed){seq+=1;for message in &mut msg{if let ContentBlock::Text{text}=&mut message.content[0]{text.replace_range(0..24,&format!("{:024}",seq));}}let t=Instant::now();let mut attempt=0;loop{attempt+=1;match checkpoint(&p,&msg,&mode){Ok(())=>{s.oklat.push(t.elapsed().as_secs_f64()*1000.);break;},Err(e)=>{if busy(&e){s.attempt_busy+=1;if (mode=="retry"||mode=="combo")&&attempt<4&&t.elapsed().as_secs_f64()<7.7{let backoff=(10u64<<attempt.min(5)).min(200)+(id as u64*7+seq as u64*3)%17;thread::sleep(Duration::from_millis(backoff));continue;}s.failed+=1;}else{s.other.push(e.to_string());}break;}}}s.lat.push(t.elapsed().as_secs_f64()*1000.);s.ops+=1;if let Ok(ms)=std::env::var("WRITER_PAUSE_MS"){thread::sleep(Duration::from_millis(ms.parse().unwrap()));}}s}));}
 for p in permits.iter().take(m).cloned(){let b=barrier.clone();let stop=stop.clone();let mode=mode.clone();readers.push(thread::spawn(move||{let mut s=Stats::default();b.wait();while !stop.load(Ordering::Relaxed){let t=Instant::now();let guarded=mode!="cache10"||s.ops%10==0;let result=if guarded{s.guard_calls+=1;p.mutation_guard().map(|g|{if hold_us>0{thread::sleep(Duration::from_micros(hold_us));}drop(g);})}else{Ok(())};match result{Ok(())=>s.oklat.push(t.elapsed().as_secs_f64()*1000.),Err(e)=>{if busy(&e){s.attempt_busy+=1;s.failed+=1;}else{s.other.push(e.to_string());}}}s.lat.push(t.elapsed().as_secs_f64()*1000.);s.ops+=1;thread::sleep(Duration::from_millis(1));}s}));}
 barrier.wait();thread::sleep(Duration::from_secs_f64(seconds));stop.store(true,Ordering::Relaxed);let mut w=Stats::default();let mut r=Stats::default();for h in writers{merge(&mut w,h.join().unwrap());}for h in readers{merge(&mut r,h.join().unwrap());}let elapsed=started.elapsed().as_secs_f64();
 let check=Connection::open(&path).unwrap();let integrity:String=check.query_row("PRAGMA quick_check",[],|r|r.get(0)).unwrap();drop(check);assert_eq!(integrity,"ok");
 println!("{}",json!({"mode":mode,"requested_bytes":size,"payload_bytes":payload_len,"n":n,"m":m,"seconds":seconds,"elapsed_seconds":elapsed,"hold_us":hold_us,"rep":rep,"journal":journal,"synchronous":sync,"sqlite":rusqlite::version(),"writers":stats(w),"readers":stats(r),"quick_check":integrity}));std::fs::remove_file(path).unwrap();
}
fn fence(){let path=Path::new(ROOT).join("fence-worker152.db");let _=std::fs::remove_file(&path);let mut reg=Registry::open(&path).unwrap();let owner=ThreadOwner::new("t".into(),Lease{owner_id:"old".into(),generation:1,expires_at:1});reg.start(&owner).unwrap();let p=OwnerPermit{registry_path:path.clone(),thread_id:owner.thread_id,lease:owner.lease,run_id:None};let cached=p.mutation_guard().is_ok();let guard=p.mutation_guard().unwrap();let(path2,p2)=(path.clone(),p.clone());let h=thread::spawn(move||{let t=Instant::now();let r=Registry::open_existing(&path2).unwrap().update("t",|o|o.claim(&p2.lease,"new".into(),1000000,1));(r,t.elapsed())});thread::sleep(Duration::from_millis(100));assert!(!h.is_finished());drop(guard);let(res,wait)=h.join().unwrap();assert!(res.is_ok());assert!(p.mutation_guard().is_err());println!("{}",json!({"fence_test":"pass","shared_guard_blocked_claim_ms":wait.as_millis(),"fresh_guard_rejects_old_generation":true,"cached_guard_would_allow":cached}));drop(reg);std::fs::remove_file(path).unwrap();}
fn main(){let a:Vec<String>=std::env::args().collect();if a.get(1).map(String::as_str)==Some("fence"){fence();return;}if a.len()<8{eprintln!("mode bytes N M seconds hold_us rep");return;}run(a[1].clone(),a[2].parse().unwrap(),a[3].parse().unwrap(),a[4].parse().unwrap(),a[5].parse().unwrap(),a[6].parse().unwrap(),a[7].parse().unwrap());}
